```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let lines = [];
let lineCount = 0;

rl.on('line', (line) => {
    lines.push(line);
    lineCount++;

    if (lineCount === 2) {
        const n = parseInt(lines[0].trim());
        const m = parseInt(lines[1].trim());

        const grid = Array.from({ length: n }, () => Array(m).fill(false));

        let ret = false;

        while (true) {
            let found = false;

            for (let i = 0; i < n && !found; i++) {
                for (let j = 0; j < m && !found; j++) {
                    if (!grid[i][j]) {
                        for (let k = 0; k < n; k++) {
                            grid[k][j] = true;
                        }
                        for (let k = 0; k < m; k++) {
                            grid[i][k] = true;
                        }
                        found = true;
                        break;
                    }
                }
            }

            if (!found) {
                break;
            }

            ret = !ret;
        }

        if (!ret) {
            console.log("Malvika");
        } else {
            console.log("Akshat");
        }

        rl.close();
    }
});
